55	// configureFlowDeps contains side effects used by the interactive configure
56	// flow. Tests can replace individual operations without a keyring, browser,
57	// GitHub CLI, or live control plane.
58	type configureFlowDeps struct {
59		resolveAuth  func(context.Context) (statusTarget, error)
