99	func runConfigureOnboardingFlow(cmd *cobra.Command, opts EnableOptions, deps configureFlowDeps) error {
100		cmd.SilenceUsage = true
101		ctx := cmd.Context()
102		outW, errW := cmd.OutOrStdout(), cmd.ErrOrStderr()
103	
104		repoRoot, err := paths.WorktreeRoot(ctx)
105		if err != nil {
106			fmt.Fprintln(errW, "Not a git repository. Please run 'entire configure' from within a git repository.")
107			return NewSilentError(errors.New("not a git repository"))
108		}
109		owner, repo, cleanRemote, err := configureRepoIdentity(ctx)
110		if err != nil {
111			return err
112		}
113	
114		profile, err := ensureConfigureLogin(ctx, outW, errW, deps)
115		if err != nil {
116			return err
117		}
118	
119		reporter, err := deps.accessClient(ctx)
120		if err != nil {
121			return fmt.Errorf("connect to Entire: %w", err)
122		}
123		access, err := reporter.ReportEnable(ctx, cleanRemote)
124		if err != nil {
125			return fmt.Errorf("check repository access: %w", err)
126		}
127		if !access.Connected {
128			if err := ensureConfigureRepoAccess(ctx, outW, errW, reporter, access, cleanRemote, owner, repo, deps); err != nil {
129				return err
130			}
131		}
132	
133		client, err := deps.coreClient()
134		if err != nil {
135			return fmt.Errorf("connect to Entire control plane: %w", err)
136		}
137		placements, err := resolvePullablePlacements(ctx, client, owner, repo)
138		if err != nil {
139			return renderCoreError(err)
140		}
141		if len(placements) == 0 {
142			placements, err = configureCreateMirrors(ctx, outW, errW, client, owner, repo, profile.Jurisdiction)
143			if err != nil {
144				return err
145			}
146		}
147		if len(placements) == 0 {
148			return errors.New("no usable mirror was selected")
149		}
150	
151		manageRegionsHint := ""
152		if admin, adminErr := deps.githubAdmin(ctx, owner, repo); adminErr == nil && admin {
153			manageRegionsHint = fmt.Sprintf("Manage regions: entire repo mirror create · or %s/gh/%s/%s/settings",
154				configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo))
155		}
156		before, err := configureGitChanges(ctx, repoRoot)
157		if err != nil {
158			return err
159		}
160		branch, branchErr := gitRunner(ctx, repoRoot, "branch", "--show-current")
161		if branchErr != nil {
162			// Best-effort: local-only saves do not need a branch.
163			branch = ""
164		}
165		protected := false
166		if branch != "" {
167			if detected, protectionErr := configureBranchProtected(ctx, owner, repo, branch); protectionErr == nil {
168				// Advisory only; git push remains authoritative.
169				protected = detected
170			}
171		}
172		chosen, selectedAgents, saveChoice, agentsChanged, err := promptConfigureUpstreamAndAgents(
173			ctx, errW, repoRoot, placements, profile.Jurisdiction, manageRegionsHint,
174			branch, protected, len(before) == 0,
175		)
176		if err != nil {
177			return err
178		}
179		if saveChoice == configureSaveCancel {
180			fmt.Fprintln(outW, "Configuration cancelled.")
181			return nil
182		}
183		if saveChoice == "" {
184			fmt.Fprintln(outW, "No configuration changes.")
185			return nil
186		}
187		if err := configureUseMirror(ctx, outW, errW, repoRoot, owner, repo, chosen); err != nil {
188			return err
189		}
190	
191		if agentsChanged {
192			opts = configureOnboardingEnableOptions(opts)
193			if err := runEnableInteractive(ctx, outW, selectedAgents, opts); err != nil {
194				return err
195			}
196			// A local enabled:false override must not win over the newly written project
197			// configuration. setEnabledFlag updates the project and synchronizes an
198			// existing local override without replacing its other local-only fields.
199			if err := setEnabledFlag(ctx, true, true); err != nil {
200				return err
201			}
202		}
203	
204		after, err := configureGitChanges(ctx, repoRoot)
205		if err != nil {
206			return err
207		}
208		generated := newConfigureChanges(before, after)
209		if agentsChanged {
210			fmt.Fprintf(outW, "✓ Wrote %s\n", configDisplayProject)
211		}
212	
213		if saveChoice == configureSaveDirect || saveChoice == configureSaveNewBranch {
214			if err := configureSaveAndPush(cmd, repoRoot, owner, repo, before, generated, branch, protected, saveChoice, deps.now); err != nil {
215				return err
216			}
217		} else if agentsChanged && len(generated) > 0 {
218			fmt.Fprintln(outW, "  Configuration was saved locally. Review and commit it normally when ready.")
219		}
220		fmt.Fprintln(outW, "✓ Configuration complete")
221		fmt.Fprintln(outW)
222		fmt.Fprintln(outW, "  You're set. Start a session with any selected agent —")
223		fmt.Fprintf(outW, "  checkpoints will show up on %s/gh/%s/%s\n", configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo))
224		return nil
225	}
