243	func configureRepoIdentity(ctx context.Context) (owner, repo, cleanRemote string, err error) {
244		raw, err := gitremote.GetRemoteURL(ctx, defaultMirrorRemote)
245		if err != nil {
246			return "", "", "", fmt.Errorf("read origin remote: %w", err)
247		}
