249		if err != nil {
250			return "", "", "", fmt.Errorf("parse origin remote: %w", err)
251		}
252		if info.Forge != mirrorUseForge {
253			return "", "", "", errors.New("interactive configure currently requires a GitHub origin remote")
254		}
255		clean, err := cleanRemoteURLForReport(raw)
