262	func ensureConfigureLogin(ctx context.Context, outW, errW io.Writer, deps configureFlowDeps) (*authProfile, error) {
263		target, err := deps.resolveAuth(ctx)
264		if err != nil {
265			return nil, err
266		}
267		if target.token != "" {
268			if profile, profileErr := deps.fetchProfile(ctx, target.coreURL, target.token); profileErr == nil {
269				return profile, nil
270			} else if !isKeychainTokenRejected(profileErr) {
271				return nil, fmt.Errorf("validate login: %w", profileErr)
272			}
273		}
274	
275		if err := deps.runLogin(ctx, outW, errW); err != nil {
276			return nil, fmt.Errorf("login: %w", err)
277		}
278		target, err = deps.resolveAuth(ctx)
279		if err != nil {
280			return nil, err
281		}
282		if target.token == "" {
283			return nil, errors.New("login completed without an active session")
284		}
285		profile, err := deps.fetchProfile(ctx, target.coreURL, target.token)
286		if err != nil {
287			return nil, fmt.Errorf("validate login: %w", err)
288		}
289		fmt.Fprintf(outW, "✓ Logged in as %s\n", profile.Handle)
290		return profile, nil
291	}
