293	func ensureConfigureRepoAccess(ctx context.Context, outW, errW io.Writer, reporter configureAccessReporter, initial *api.EnableRepoResponse, cleanRemote, owner, repo string, deps configureFlowDeps) error {
294		fmt.Fprintf(errW, "✗ Entire has no access to %s/%s\n\n", owner, repo)
295		installURL := strings.TrimSpace(initial.InstallURL)
296		if installURL == "" {
297			installURL = fmt.Sprintf("%s/install?repo=%s%%2F%s", configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo))
298		}
299	
300		admin, adminErr := deps.githubAdmin(ctx, owner, repo)
301		if adminErr == nil && !admin {
302			fmt.Fprintln(errW, "  An admin needs to install the GitHub app first.")
303			fmt.Fprintln(errW, "  Send them this link to continue:")
304			fmt.Fprintf(errW, "\n  %s\n", installURL)
305			return NewSilentError(errors.New("GitHub app installation required"))
306		}
307		if adminErr != nil {
308			switch {
309			case errors.Is(adminErr, errConfigureGHUnavailable):
310				fmt.Fprintln(errW, "  Could not verify GitHub admin access because the gh CLI is not installed.")
311				fmt.Fprintln(errW, "  Install it from https://cli.github.com/ and run `gh auth login` for future checks.")
312			case errors.Is(adminErr, errConfigureGHUnauthenticated):
313				fmt.Fprintln(errW, "  Could not verify GitHub admin access because the gh CLI is not authenticated.")
314				fmt.Fprintln(errW, "  Run `gh auth login` for future checks.")
315			default:
316				fmt.Fprintf(errW, "  Could not verify GitHub admin access: %v\n", adminErr)
317			}
318			fmt.Fprintln(errW, "  If you administer this repository, you can still continue with the installation link.")
319			fmt.Fprintln(errW)
320		}
321	
322		fmt.Fprintln(outW, "  Install the GitHub app to grant access:")
323		fmt.Fprintf(outW, "  %s\n\n", installURL)
324		if err := deps.openURL(ctx, installURL); err != nil {
325			fmt.Fprintln(outW, "  Open the link above in your browser.")
326		}
327		stop := startSpinner(errW, "Waiting for installation")
328		stopped := false
329		defer func() {
330			if !stopped {
331				stop(false)
332			}
333		}()
334	
335		waitCtx, cancel := context.WithTimeout(ctx, configureAccessWaitTimeout)
336		defer cancel()
337		ticker := time.NewTicker(configureAccessPollInterval)
338		defer ticker.Stop()
339		for {
340			select {
341			case <-waitCtx.Done():
342				return fmt.Errorf("waiting for GitHub app installation: %w", waitCtx.Err())
343			case <-ticker.C:
344				access, err := reporter.ReportEnable(waitCtx, cleanRemote)
345				if err == nil && access.Connected {
346					stop(true)
347					stopped = true
348					fmt.Fprintln(outW, "✓ Access granted")
349					return nil
350				}
351			}
352		}
353	}
