355	func configureGitHubAdmin(ctx context.Context, owner, repo string) (bool, error) {
356		runner := execRunner{}
357		if !ghAvailable(ctx, runner) {
358			return false, errConfigureGHUnavailable
359		}
360		if !ghAuthenticated(ctx, runner) {
361			return false, errConfigureGHUnauthenticated
362		}
363		out, err := runner.Run(ctx, "gh", "api", "repos/"+owner+"/"+repo, "--jq", ".permissions.admin")
364		if err != nil {
365			return false, fmt.Errorf("check GitHub admin permission: %w", err)
366		}
367		admin, err := strconv.ParseBool(strings.TrimSpace(out))
368		if err != nil {
369			return false, fmt.Errorf("parse GitHub admin permission: %w", err)
370		}
371		return admin, nil
372	}
