374	func configureCreateMirrors(ctx context.Context, outW, errW io.Writer, client *coreapi.Client, owner, repo, jurisdiction string) ([]coreapi.ResolvedPlacement, error) {
375		regions, err := availableRegions(ctx, client)
376		if err != nil {
377			return nil, fmt.Errorf("list regions: %w", err)
378		}
379		if len(regions) == 0 {
380			return nil, errors.New("no regions available to mirror into")
381		}
382		selected, err := pickConfigureRegions(ctx, outW, regions, jurisdiction)
383		if err != nil {
384			return nil, err
385		}
386		results := createMirrors(ctx, errW, mirrorTargets([]coreapi.AvailableMirror{{Owner: owner, Repo: repo}}, selected), false, 30*time.Minute)
387		if err := reportMirrorResults(outW, errW, results); err != nil {
388			return nil, err
389		}
390		placements := make([]coreapi.ResolvedPlacement, 0, len(results))
391		for i, result := range results {
392			if result.err != nil || result.cloneURL == "" {
393				continue
394			}
395			region := selected[i]
396			placements = append(placements, coreapi.ResolvedPlacement{
397				ClusterHost:  region.host,
398				Cell:         coreapi.NewOptString(region.slug),
399				Jurisdiction: coreapi.NewOptString(region.jurisdiction),
400			})
401		}
402		return placements, nil
403	}
