406		opts, defaults := clusterChoices(regions, jurisdiction)
407		byHost := make(map[string]regionChoice, len(regions))
408		for _, region := range regions {
409			byHost[region.host] = region
410		}
411		selected := append([]string(nil), defaults...)
412		form := NewAccessibleForm(huh.NewGroup(
413			huh.NewMultiSelect[string]().
414				Title("Which regions should this repository live in?").
415				Description("Space to select, enter to confirm — your data stays in the selected regions.").
416				Options(opts...).
417				Height(multiSelectHeight(len(opts))).
418				Validate(func(values []string) error {
419					if len(values) == 0 {
420						return errors.New("select at least one region")
421					}
422					return nil
423				}).
424				Value(&selected),
425		))
426		if err := form.RunWithContext(ctx); err != nil {
