649	func sameStrings(a, b []string) bool {
650		if len(a) != len(b) {
651			return false
652		}
653		seen := make(map[string]int, len(a))
654		for _, value := range a {
655			seen[value]++
656		}
657		for _, value := range b {
658			seen[value]--
659			if seen[value] < 0 {
660				return false
661			}
662		}
663		return true
664	}
