666	func configureRadioKeyBinds(selectField *huh.Select[string]) []key.Binding {
667		bindings := selectField.KeyBinds()
668		for i := range bindings {
669			help := bindings[i].Help()
670			if help.Key == "enter" && help.Desc == "select" {
671				bindings[i].SetHelp("enter", "continue")
672			}
673		}
674		return append(bindings, key.NewBinding(key.WithKeys("space"), key.WithHelp("space", "select")))
675	}
