685	// promptConfigureUpstreamAndAgents presents upstream, agents, and the dynamic
686	// save action as one persistent form. Save is always visible, while its actions
687	// change based on whether the choices require only local state or a commit and
688	// push. Arrow keys stay within the active section; Enter advances, while
689	// shift+tab revisits the previous section.
690	func promptConfigureUpstreamAndAgents(ctx context.Context, errW io.Writer, repoRoot string, placements []coreapi.ResolvedPlacement, jurisdiction, manageRegionsHint, branch string, protected, cleanWorktree bool) (coreapi.ResolvedPlacement, []agent.Agent, string, bool, error) {
691		currentHost := configureCurrentUpstream(ctx, repoRoot)
692		placements = configurePlacementOrder(placements, currentHost, jurisdiction)
693		if len(placements) == 0 {
694			return coreapi.ResolvedPlacement{}, nil, "", false, errors.New("no upstreams available")
695		}
696	
697		// configurePlacementOrder puts the configured upstream first, so it is also
698		// the initial selection. If this repo has no Entire upstream yet, it falls
699		// back to the jurisdiction-preferred placement.
700		selectedHost := placements[0].ClusterHost
701		placementByHost := make(map[string]coreapi.ResolvedPlacement, len(placements))
702		for _, placement := range placements {
703			placementByHost[placement.ClusterHost] = placement
704		}
705		upstreamOptions := func() []huh.Option[string] {
706			return configureUpstreamOptions(placements, selectedHost, currentHost)
707		}
708	
709		external.DiscoverAndRegisterAlways(ctx)
710		preselected := configureAgentPreselection(ctx)
711		agentOptions := configureAgentOptions(hookAgentOptions(preselected), preselected)
712		if len(agentOptions) == 0 {
713			return coreapi.ResolvedPlacement{}, nil, "", false, errors.New("no agents with hook support available")
714		}
715		installedAgentNames := make([]string, 0)
716		for _, name := range GetAgentsWithHooksInstalled(ctx) {
717			installedAgentNames = append(installedAgentNames, string(name))
718		}
719		selectedAgentNames := make([]string, 0, len(preselected))
720		for _, option := range agentOptions {
721			if _, ok := preselected[types.AgentName(option.Value)]; ok {
722				selectedAgentNames = append(selectedAgentNames, option.Value)
723			}
724		}
725	
726		// huh's footer already documents navigation. Keep field descriptions for
727		// contextual information only, rather than repeating keyboard controls.
728		upstreamDescription := manageRegionsHint
729		upstreamControl := &configureUpstreamField{
730			value:       &selectedHost,
731			committed:   selectedHost,
732			highlighted: selectedHost,
733		}
734		upstreamControl.Select = huh.NewSelect[string]().
735			TitleFunc(func() string {
736				return configureQuestionTitle("Which upstream do you want to use?", upstreamControl.focused)
737			}, &upstreamControl.focused).
738			Description(upstreamDescription).
739			Options(upstreamOptions()...).
740			Height(configureFieldHeight(len(placements), upstreamDescription)).
741			Value(&selectedHost)
742		upstreamControl.refresh = func() {
743			upstreamControl.Options(upstreamOptions()...)
744		}
745	
746		agentControl := &configureAgentField{value: &selectedAgentNames}
747		agentControl.MultiSelect = huh.NewMultiSelect[string]().
748			TitleFunc(func() string {
749				return configureQuestionTitle("Select the agents you want to use", agentControl.focused)
750			}, &agentControl.focused).
751			Options(agentOptions...).
752			// MultiSelect subtracts its title from an implicit viewport height, so
753			// include exactly one title row to show every option without padding.
754			Height(len(agentOptions) + 1).
755			Validate(func(values []string) error {
756				if len(values) == 0 {
757					return errors.New("select at least one agent")
758				}
759				return nil
760			}).
761			Value(&selectedAgentNames)
762	
763		mirrorChanged := func() bool {
764			mirror, _ := configureSelectionChanges(selectedHost, currentHost, selectedAgentNames, installedAgentNames)
765			return mirror
766		}
767		agentsChanged := func() bool {
768			_, agents := configureSelectionChanges(selectedHost, currentHost, selectedAgentNames, installedAgentNames)
769			return agents
770		}
771		requiresPush := func() bool {
772			return agentsChanged() && cleanWorktree && branch != ""
773		}
774		hasChanges := func() bool {
775			return mirrorChanged() || agentsChanged()
776		}
777	
778		previousHasChanges := hasChanges()
779		saveChoice := defaultConfigureSaveChoice(previousHasChanges, requiresPush(), protected)
780		saveControl := &configureSaveField{
781			value:       &saveChoice,
782			committed:   saveChoice,
783			highlighted: saveChoice,
784		}
785		saveOptions := func() []huh.Option[string] {
786			return configureSaveOptions(branch, protected, requiresPush(), hasChanges(), saveChoice)
787		}
788		saveControl.Select = huh.NewSelect[string]().
789			TitleFunc(func() string {
790				return configureQuestionTitle("Save configuration", saveControl.focused)
791			}, &saveControl.focused).
792			Description(configureSaveDescription(branch, protected, requiresPush(), hasChanges())).
793			Options(saveOptions()...).
794			Height(configureFieldHeight(len(saveOptions()), configureSaveDescription(branch, protected, requiresPush(), hasChanges()))).
795			Value(&saveChoice)
796		refreshSave := func() {
797			changed := hasChanges()
798			options := saveOptions()
799			if changed != previousHasChanges || !configureOptionsContain(options, saveChoice) {
800				saveChoice = defaultConfigureSaveChoice(changed, requiresPush(), protected)
801				saveControl.committed = saveChoice
802				saveControl.highlighted = saveChoice
803				options = saveOptions()
804			}
805			previousHasChanges = changed
806			description := configureSaveDescription(branch, protected, requiresPush(), changed)
807			saveControl.Select.
808				Description(description).
809				Height(configureFieldHeight(len(options), description)).
810				Options(options...)
811		}
812		saveControl.refresh = refreshSave
813		upstreamControl.layoutChanged = refreshSave
814		agentControl.selectionChanged = refreshSave
815		agentControl.showSave = func() bool { return true }
816	
817		group := huh.NewGroup(upstreamControl, agentControl, saveControl)
818		form := newConfigureForm(group)
819		// Separate the form from the shell prompt or preceding onboarding status.
820		fmt.Fprintln(errW)
821		if err := form.RunWithContext(ctx); err != nil {
822			if cancelErr := handleFormCancellation(errW, "Configure", err); cancelErr != nil {
823				return coreapi.ResolvedPlacement{}, nil, "", false, cancelErr
824			}
825			return coreapi.ResolvedPlacement{}, nil, "", false, NewSilentError(errors.New("configure cancelled"))
826		}
827	
828		chosen, ok := placementByHost[selectedHost]
829		if !ok {
830			return coreapi.ResolvedPlacement{}, nil, "", false, errors.New("selected upstream is no longer available")
831		}
832		selectedAgents := make([]agent.Agent, 0, len(selectedAgentNames))
833		for _, name := range selectedAgentNames {
834			ag, err := agent.Get(types.AgentName(name))
835			if err != nil {
836				return coreapi.ResolvedPlacement{}, nil, "", false, fmt.Errorf("load selected agent %q: %w", name, err)
837			}
838			selectedAgents = append(selectedAgents, ag)
839		}
840		if !hasChanges() && saveChoice != configureSaveCancel {
841			saveChoice = ""
842		}
843		return chosen, selectedAgents, saveChoice, agentsChanged(), nil
844	}
