846	func configureUpstreamOptions(placements []coreapi.ResolvedPlacement, selectedHost, currentHost string) []huh.Option[string] {
847		options := make([]huh.Option[string], 0, len(placements))
848		for _, placement := range placements {
849			selected := placement.ClusterHost == selectedHost
850			label := configureRadioLabel(configurePlacementLabel(placement), selected)
851			if strings.EqualFold(placement.ClusterHost, currentHost) {
852				tag := lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Muted)).Render("— current")
853				label += " " + tag
854			}
855			options = append(options, huh.NewOption(label, placement.ClusterHost))
856		}
857		return options
858	}
