862		// option. huh otherwise gives dynamic Select fields spare viewport rows,
863		// which accumulate as increasingly large gaps between form sections.
864		height := optionCount + 1
865		if description != "" {
866			height += lipgloss.Height(description)
867		}
868		return height
869	}
