943	func newConfigureForm(groups ...*huh.Group) *huh.Form {
944		// Do not start with NewAccessibleForm here: huh fields retain the first
945		// theme assigned to them, so applying configureFormTheme afterward would
946		// leave the standard rail and `>` cursor in place. Install this theme first.
947		form := huh.NewForm(groups...).WithTheme(configureFormTheme())
948		if IsAccessibleMode() {
949			form = form.WithAccessible(true)
950		}
