954	func configureFormTheme() huh.Theme {
955		return huh.ThemeFunc(func(isDark bool) *huh.Styles {
956			theme := uiform.Theme().Theme(isDark)
957			success := lipgloss.Color(palette.Success)
958			muted := lipgloss.Color(palette.Muted)
959	
960			// Radio and checkbox lists use the same active-row indicator. Selection
961			// remains green and independent from the orange `>` cursor.
962			theme.FieldSeparator = lipgloss.NewStyle().SetString("")
963			theme.Focused.Base = lipgloss.NewStyle()
964			theme.Blurred.Base = lipgloss.NewStyle()
965			theme.Focused.SelectSelector = lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Warning)).SetString("> ")
966			theme.Blurred.SelectSelector = lipgloss.NewStyle().SetString("  ")
967			theme.Focused.MultiSelectSelector = lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Warning)).SetString("> ")
968			theme.Blurred.MultiSelectSelector = lipgloss.NewStyle().SetString("  ")
969			theme.Focused.SelectedPrefix = lipgloss.NewStyle().Foreground(success).SetString("◼ ")
970			theme.Blurred.SelectedPrefix = lipgloss.NewStyle().Foreground(success).SetString("◼ ")
971			theme.Focused.UnselectedPrefix = lipgloss.NewStyle().Foreground(muted).SetString("◻ ")
972			theme.Blurred.UnselectedPrefix = lipgloss.NewStyle().Foreground(muted).SetString("◻ ")
973			theme.Focused.SelectedOption = theme.Focused.SelectedOption.UnsetForeground()
974			theme.Blurred.SelectedOption = theme.Blurred.SelectedOption.UnsetForeground()
975			theme.Focused.UnselectedOption = theme.Focused.UnselectedOption.Foreground(muted)
976			theme.Blurred.UnselectedOption = theme.Blurred.UnselectedOption.Foreground(muted)
977			return theme
978		})
979	}
