981	func configureQuestionTitle(question string, focused bool) string {
982		color := palette.Muted
983		if focused {
984			color = palette.Warning
985		}
986		marker := lipgloss.NewStyle().Foreground(lipgloss.Color(color)).Render("?")
987		return marker + " " + question
988	}
