1035	func configurePlacementOrder(placements []coreapi.ResolvedPlacement, currentHost, jurisdiction string) []coreapi.ResolvedPlacement {
1036		ordered := append([]coreapi.ResolvedPlacement(nil), placements...)
1037		sort.SliceStable(ordered, func(i, j int) bool {
1038			iCurrent := strings.EqualFold(ordered[i].ClusterHost, currentHost)
1039			jCurrent := strings.EqualFold(ordered[j].ClusterHost, currentHost)
1040			if iCurrent != jCurrent {
1041				return iCurrent
1042			}
1043			iHome := strings.EqualFold(ordered[i].Jurisdiction.Or(""), jurisdiction)
1044			jHome := strings.EqualFold(ordered[j].Jurisdiction.Or(""), jurisdiction)
1045			if currentHost == "" && iHome != jHome {
1046				return iHome
