1079	func configureUseMirror(ctx context.Context, outW, errW io.Writer, repoRoot, owner, repo string, chosen coreapi.ResolvedPlacement) error {
1080		remotes, err := listGitRemotes(ctx, repoRoot)
1081		if err != nil {
1082			return err
1083		}
1084		current := ""
1085		if remotes[defaultMirrorRemote] {
1086			current, err = gitremote.GetRemoteURLInDir(ctx, repoRoot, defaultMirrorRemote)
1087			if err != nil {
1088				return fmt.Errorf("read origin remote URL: %w", err)
1089			}
1090		}
1091		mirrorURL := mirrorCloneURL(chosen.ClusterHost, owner, repo)
1092		preserve := defaultMirrorUpstreamRemote
1093		// An existing forge alias already preserves direct GitHub access. Avoid
1094		// manufacturing another alias, and never preserve an old Entire placement
1095		// under the misleading name "upstream".
1096		if info, parseErr := gitremote.ParseURL(current); parseErr == nil && info.Protocol == gitremote.ProtocolEntire {
1097			preserve = ""
1098		}
1099		plan := planMirrorRemote(defaultMirrorRemote, mirrorURL, current, preserve, remotes)
1100		if err := applyMirrorRemotePlan(ctx, repoRoot, plan); err != nil {
1101			return err
1102		}
1103		// Repointing origin can be lossy when the usual preservation name already
1104		// exists. Report the complete plan just like `repo mirror use`, including the
1105		// redacted former URL and its recovery command.
1106		reportMirrorRemotePlan(outW, errW, plan)
1107		return nil
1108	}
1109	
1110	// configureGitChanges returns porcelain status keyed by path. Its values retain
1111	// XY so callers can detect whether anything was already staged before the flow.
1112	func configureGitChanges(ctx context.Context, repoRoot string) (map[string]string, error) {
1113		out, err := gitRunner(ctx, repoRoot, "status", "--porcelain=v1", "--untracked-files=all")
1114		if err != nil {
1115			return nil, fmt.Errorf("read git status: %w", err)
1116		}
1117		changes := make(map[string]string)
1118		for _, line := range strings.Split(out, "\n") {
1119			if len(line) < 4 {
1120				continue
1121			}
1122			path := strings.TrimSpace(line[3:])
1123			if arrow := strings.LastIndex(path, " -> "); arrow >= 0 {
1124				path = path[arrow+4:]
1125			}
1126			if path != "" {
1127				changes[path] = line[:2]
1128			}
1129		}
1130		return changes, nil
1131	}
1132	
1133	func newConfigureChanges(before, after map[string]string) []string {
1134		paths := make([]string, 0, len(after))
1135		for path := range after {
1136			if _, existed := before[path]; !existed {
1137				paths = append(paths, path)
1138			}
1139		}
1140		sort.Strings(paths)
1141		return paths
1142	}
1143	
1144	func configureSaveAndPush(cmd *cobra.Command, repoRoot, owner, repo string, before map[string]string, generated []string, branch string, protected bool, choice string, now func() time.Time) error {
1145		outW := cmd.OutOrStdout()
1146		if len(generated) == 0 {
1147			fmt.Fprintln(outW, "  No new configuration changes to commit.")
1148			return nil
1149		}
1150		if len(before) != 0 {
1151			fmt.Fprintln(outW, "  Configuration was saved but not committed because the worktree already had changes.")
1152			fmt.Fprintln(outW, "  Review and commit the configuration normally when ready.")
1153			return nil
1154		}
1155	
1156		if branch == "" {
1157			return errors.New("cannot save configuration from a detached HEAD")
1158		}
1159		if protected && choice == configureSaveDirect {
1160			return fmt.Errorf("%s is protected; push to a new branch", branch)
1161		}
1162		if choice != configureSaveDirect && choice != configureSaveNewBranch {
1163			return fmt.Errorf("unknown save choice %q", choice)
1164		}
1165	
1166		pushBranch := branch
1167		if choice == configureSaveNewBranch {
1168			var err error
1169			pushBranch, err = availableConfigureBranch(cmd.Context(), repoRoot, now)
1170			if err != nil {
1171				return err
1172			}
1173			if _, err := gitRunner(cmd.Context(), repoRoot, "switch", "-c", pushBranch); err != nil {
1174				return fmt.Errorf("create configuration branch: %w", err)
1175			}
1176		}
1177	
1178		args := []string{"add", "--"}
1179		args = append(args, generated...)
1180		if _, err := gitRunner(cmd.Context(), repoRoot, args...); err != nil {
1181			return fmt.Errorf("stage configuration: %w", err)
1182		}
1183		if _, err := gitRunner(cmd.Context(), repoRoot, "commit", "-m", configureCommitMessage); err != nil {
1184			return fmt.Errorf("commit configuration: %w", err)
1185		}
1186		sha, err := gitRunner(cmd.Context(), repoRoot, "rev-parse", "--short", "HEAD")
1187		if err != nil {
1188			return fmt.Errorf("read configuration commit: %w", err)
1189		}
1190		fmt.Fprintf(outW, "✓ Committed %s · %s\n", configureCommitMessage, sha)
1191		if _, err := gitRunner(cmd.Context(), repoRoot, "push", "-u", defaultMirrorRemote, pushBranch); err != nil {
1192			return fmt.Errorf("push configuration: %w", err)
1193		}
1194		fmt.Fprintf(outW, "✓ Pushed to %s/%s\n", defaultMirrorRemote, pushBranch)
1195		if choice == configureSaveNewBranch {
1196			fmt.Fprintln(outW, "  Open a trail to merge it:")
1197			fmt.Fprintf(outW, "  %s/gh/%s/%s/trails/new?branch=%s\n", configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo), url.QueryEscape(pushBranch))
1198		}
1199		return nil
1200	}
1201	
1202	func configureBranchProtected(ctx context.Context, owner, repo, branch string) (bool, error) {
1203		out, err := exec.CommandContext(ctx, "gh", "api", "repos/"+owner+"/"+repo+"/branches/"+url.PathEscape(branch), "--jq", ".protected").Output()
1204		if err != nil {
1205			return false, fmt.Errorf("check GitHub branch protection: %w", err)
1206		}
1207		protected, err := strconv.ParseBool(strings.TrimSpace(string(out)))
1208		if err != nil {
1209			return false, fmt.Errorf("parse GitHub branch protection: %w", err)
1210		}
1211		return protected, nil
1212	}
1213	
1214	func availableConfigureBranch(ctx context.Context, repoRoot string, now func() time.Time) (string, error) {
1215		candidates := []string{configureBranchBase, configureBranchBase + "-" + now().Format("20060102-150405")}
1216		for _, candidate := range candidates {
1217			_, err := gitRunner(ctx, repoRoot, "show-ref", "--verify", "--quiet", "refs/heads/"+candidate)
1218			if err == nil {
1219				continue // branch already exists
1220			}
1221			var exitErr *exec.ExitError
1222			if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
1223				return candidate, nil // show-ref uses 1 for a missing ref
1224			}
1225			return "", fmt.Errorf("check configuration branch %q: %w", candidate, err)
1226		}
1227		return "", errors.New("could not choose an unused configuration branch name")
1228	}
